    public const string DisassemblerFormat =
        """
        // <auto-generated />
        #nullable enable
        using System;

        namespace {0};

        /// <summary>
        /// Simple wrapper class for the <see cref="Disassemble"/> method.
        /// </summary>
        /// <remarks>{1} instructions registered.</remarks>
        public class Disassembler : Mercury.Engine.Common.IInstructionDisassembler {{
            
            /*
             * Width ladder: tries to match every possible size progressively, from the
             * smallest to the biggest. Decoder pulls bytes progressively when needed
             * using the IInstructionByteSource interface.
             */
            public const int MinWidth = {2};
            public const int MaxWidth = {3};
            public const int WidthStep = {4};

            public global::Mercury.Engine.Common.IInstruction? Decode(Mercury.Engine.Common.IInstructionByteSource source, Mercury.Engine.Common.IInstructionPool pool) {{
                if(pool is not InstructionPool poolSpecific) {{
                    throw new Exception($"Wrong instruction pool type. Should be {0}.InstructionPool, but was {{pool.GetType().FullName}} instead.");
                }}
                return Disassemble(source, poolSpecific);
            }}

            private static global::Mercury.Engine.Common.IInstruction? GetType(global::System.ReadOnlySpan<byte> bytes, int widthBytes, global::Mercury.Engine.Memory.Endianness endianness, InstructionPool pool) {{
        {5}
                return null;
            }}
            
            public static global::Mercury.Engine.Common.IInstruction? Disassemble(Mercury.Engine.Common.IInstructionByteSource source, InstructionPool pool) {{
                Span<byte> buffer = stackalloc byte[MaxWidth];
                // check one size at a time
                for (int width = MinWidth; width <= MaxWidth; width += WidthStep) {{
                    bool complete = true;
                    for (int i = 0; i < width; i++) {{
                        if (!source.TryRead(i, out byte b)) {{
                            complete = false;
                            break;
                        }}
                        buffer[i] = b;
                    }}
                    // couldnt read all bytes for this size, didnt mathc anything
                    if (!complete) {{
                        return null;
                    }}
                    global::Mercury.Engine.Common.IInstruction? type = GetType(buffer.Slice(0, width), width, source.Endianness, pool);
                    if (type is not null) {{
                        type.FromBytes(buffer.Slice(0, width), source.Endianness);
                        return type;
                    }}
                }}
                return null;
            }}
        }}
        """;

